<script setup>
import { onMounted, onUnmounted, ref } from "vue"; import { api } from "../api";
const orders = ref([]); const query = ref(""); const status = ref(""); const busy = ref(false); const error = ref(""); const selected = ref(null);
async function load() { busy.value = true; error.value = ""; try { const params = new URLSearchParams(); if (query.value) params.set("q", query.value); if (status.value) params.set("status", status.value); orders.value = await api(`/orders?${params}`); } catch(e) { error.value=e.message; } finally { busy.value=false; } }
onMounted(() => { load(); window.addEventListener("demo-identity-changed", load); }); onUnmounted(() => window.removeEventListener("demo-identity-changed", load));
</script>
<template><div class="page-stack"><section class="welcome-row"><div><div class="eyebrow">ORDER OPERATIONS</div><h2>订单管理</h2><p>仅列出租户内经 SQL 授权的 SQLite 演示订单；MockShop 店铺订单仍通过现有单号查询接口访问。</p></div><button class="button button-secondary" @click="load">↻ 刷新</button></section>
<section class="content-card"><div class="filter-bar"><input v-model="query" placeholder="搜索订单号、商品或问题" @keyup.enter="load"><select v-model="status"><option value="">全部状态</option><option>已完成</option><option>已发货</option><option>处理中</option></select><button class="button button-primary" :disabled="busy" @click="load">搜索</button></div>
<div v-if="busy" class="state-card">正在读取授权范围内的订单…</div><div v-else-if="error" class="state-card state-error">{{error}}</div><div v-else-if="!orders.length" class="empty-state"><span class="empty-mark">▤</span><strong>当前身份暂无可见订单</strong><p>订单访问由服务端校验，前端不会扩大访问范围。</p></div>
<div v-else class="table-wrap"><table><thead><tr><th>订单号</th><th>商品</th><th>客户</th><th>状态</th><th>创建日期</th><th></th></tr></thead><tbody><tr v-for="o in orders" :key="o.order_id"><td class="mono">{{o.order_id}}</td><td>{{o.product}}</td><td>{{o.customer_id || "—"}}</td><td><span class="status-pill">{{o.status}}</span></td><td>{{o.created_date || "—"}}</td><td><button class="text-button" @click="selected=o">详情</button></td></tr></tbody></table></div></section>
<div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="detail-modal"><button class="modal-close" @click="selected=null">关闭</button><div class="eyebrow">ORDER DETAIL · DEMO</div><h3>订单 {{selected.order_id}}</h3><dl><dt>商品</dt><dd>{{selected.product}}</dd><dt>状态</dt><dd>{{selected.status}}</dd><dt>问题描述</dt><dd>{{selected.issue_description || "无记录"}}</dd><dt>订单归属</dt><dd>{{selected.customer_id || "—"}}</dd></dl><p class="muted">只读演示详情。修改订单状态功能未接入。</p></section></div></div></template>
